package cn.herohealth.app;

import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

public class ChatPolicyTest {
    private JSONObject turn(String id,String user,String answer,String status)throws Exception{JSONObject t=new JSONObject().put("id",id).put("user",user).put("status",status);if(answer!=null)t.put("assistant",answer);return t;}
    private JSONObject archive(long last)throws Exception{return new JSONObject().put("activeChatTopicId","current").put("chatTopics",new JSONArray().put(new JSONObject().put("id","old").put("lastActivityAt",last).put("turns",new JSONArray().put(turn("old-message","OLD_TOPIC_ONLY","OLD_ANSWER_ONLY","done")))).put(new JSONObject().put("id","current").put("lastActivityAt",last).put("turns",new JSONArray().put(turn("question","CURRENT_QUESTION",null,"pending")))));}
    @Test public void newTopicNeverReadsPreviousTopics()throws Exception{String sent=ChatPolicy.messages(archive(1000),"current","question",1001,new JSONArray()).toString();assertTrue(sent.contains("CURRENT_QUESTION"));assertFalse(sent.contains("OLD_TOPIC_ONLY"));assertFalse(sent.contains("OLD_ANSWER_ONLY"));}
    @Test public void expiryBoundaryAndClockRollbackRejectOldRequests()throws Exception{JSONObject s=archive(1000);ChatPolicy.pending(s,"current","question",1000+ChatPolicy.IDLE_MS-1);assertThrows(AiHttp.Failure.class,()->ChatPolicy.pending(s,"current","question",1000+ChatPolicy.IDLE_MS));assertThrows(AiHttp.Failure.class,()->ChatPolicy.pending(s,"current","question",999));}
    @Test public void rejectsWrongTopicAndSupersededTurn()throws Exception{JSONObject s=archive(1000);assertThrows(AiHttp.Failure.class,()->ChatPolicy.pending(s,"old","old-message",1001));assertThrows(AiHttp.Failure.class,()->ChatPolicy.pending(s,"current","other",1001));}
    @Test public void sameTopicUsesOnlyLatestTwelveCompletePairsAndNoEarlierImages()throws Exception{JSONObject s=archive(1000);JSONArray turns=s.getJSONArray("chatTopics").getJSONObject(1).getJSONArray("turns");turns.remove(0);for(int i=0;i<30;i++)turns.put(turn("q"+i,"u"+i,"a"+i,"done").put("image",new JSONObject().put("dataUrl","IMAGE_SENTINEL")));turns.put(turn("failed","FAILED_SENTINEL",null,"failed"));turns.put(turn("question","CURRENT",null,"pending"));JSONArray sent=ChatPolicy.messages(s,"current","question",1001,new JSONArray());assertEquals(27,sent.length());assertEquals("u18（此前附图不重复发送，以当时的文字回答为准）",sent.getJSONObject(2).getString("content"));assertFalse(sent.toString().contains("IMAGE_SENTINEL"));assertFalse(sent.toString().contains("FAILED_SENTINEL"));}
    @Test public void sameTopicLongAnswersObeyTextBudget()throws Exception{JSONObject s=archive(1000);JSONArray turns=s.getJSONArray("chatTopics").getJSONObject(1).getJSONArray("turns");turns.remove(0);for(int i=0;i<3;i++)turns.put(turn("q"+i,"u"+i,new String(new char[12000]).replace('\0','a'),"done"));turns.put(turn("question","CURRENT",null,"pending"));assertEquals(5,ChatPolicy.messages(s,"current","question",1001,new JSONArray()).length());}
    @Test public void allCardsIncludeMedicationAndHistoryButNoChatOrSettings()throws Exception{JSONObject a=archive(1000).put("settings",new JSONObject().put("privateValue","SETTINGS_SENTINEL")).put("cards",new JSONArray().put(new JSONObject().put("id","c").put("name","测试主题").put("description","测试说明").put("archived",true).put("metricIds",new JSONArray().put("w")).put("medications",new JSONArray().put(new JSONObject().put("name","虚构药品").put("status","在用"))))).put("metrics",new JSONArray().put(new JSONObject().put("id","w").put("name","测试体重").put("unit","kg"))).put("readings",new JSONArray()).put("reports",new JSONArray());for(int i=0;i<15;i++)a.getJSONArray("readings").put(new JSONObject().put("metricId","w").put("date",String.format(java.util.Locale.ROOT,"2024-01-%02d",i+1)).put("value",i));JSONArray context=HealthContext.cards(a);assertEquals(1,context.length());assertEquals(10,context.getJSONObject(0).getJSONArray("metrics").getJSONObject(0).getJSONArray("history").length());assertTrue(context.getJSONObject(0).getBoolean("archived"));assertTrue(context.toString().contains("虚构药品"));assertFalse(context.toString().contains("OLD_TOPIC_ONLY"));assertFalse(context.toString().contains("SETTINGS_SENTINEL"));}
}
